#!/bin/sh
# Public Debian 12 AArch64 reference cross qualification of opencv_geometry.
#
# Runs inside the environment of tests/cross/install_reference_tools.sh.
# Every step uses explicit target inputs:
#   1. a sysroot staged from Debian 12 arm64 packages;
#   2. a GPR configuration generated by GPRconfig 26 for Debian's
#      gnat-12-aarch64-linux-gnu and g++-12-aarch64-linux-gnu;
#   3. Core cross-built and installed by its own scripts/cross_build_core.sh
#      at the exact commit;
#   4. Geometry cross-built and installed by scripts/cross_build_geometry.sh
#      from the clean HEAD of this checkout;
#   5. independent Ada and mixed Ada/C++ consumers cross-linked against the
#      installed prefixes, before and after relocating them, and inspected;
#   6. emulated execution of the consumers and of the cross-built AUnit
#      suite under qemu-user-static, as reference evidence only.
#
# This is public reference evidence. It is not AdaCore GNAT 12 or Yocto
# Scarthgap qualification, and emulated execution is not target execution.
#
# usage: qualify_debian_aarch64_reference.sh EVIDENCE
# Inputs:
#   REFERENCE_CORE_ROOT    clean opencv_core Git checkout
#   REFERENCE_CORE_COMMIT  40-hex Core commit expected there
#   REFERENCE_AUNIT_ROOT   unpacked AUnit 26.0.0 sources
set -eu

fail() {
    echo "error: $*" >&2
    exit 1
}

expected_tests=542
here=$(CDPATH='' cd -- "$(dirname -- "$0")" && pwd)
root=$(CDPATH='' cd -- "$here/../.." && pwd)
test "$#" -eq 1 || fail "usage: qualify_debian_aarch64_reference.sh EVIDENCE"
evidence=$1
core_root=${REFERENCE_CORE_ROOT:?set REFERENCE_CORE_ROOT}
core_commit=${REFERENCE_CORE_COMMIT:?set REFERENCE_CORE_COMMIT}
aunit=${REFERENCE_AUNIT_ROOT:?set REFERENCE_AUNIT_ROOT}
case "$evidence" in /?*) ;; *) fail "absolute evidence path required" ;; esac
test ! -e "$evidence" || fail "evidence directory already exists"
test -f "$aunit/lib/gnat/aunit.gpr" || fail "not AUnit sources: $aunit"
for host in gcc g++ gnat gprbuild; do
    if command -v "$host" >/dev/null 2>&1; then
        fail "host tool on PATH: $host"
    fi
done

git_in() {
    repo=$1
    shift
    git -c "safe.directory=$repo" -C "$repo" "$@"
}
test "$(git_in "$core_root" rev-parse HEAD)" = "$core_commit" \
    || fail "Core checkout is not at $core_commit"
geometry_commit=$(git_in "$root" rev-parse HEAD)

target=aarch64-linux-gnu
tools=/opt/gprbuild-26/bin
logs=$evidence/logs
mkdir -p "$logs" "$evidence/tools"
dispositions=$evidence/dispositions.txt
: > "$dispositions"

# 1. Target sysroot from real Debian 12 arm64 packages.
sysroot=$evidence/sysroot
sh "$here/prepare_debian12_sysroot.sh" "$sysroot" "$logs" \
    > "$logs/sysroot.log" 2>&1 || fail "sysroot staging failed"

# 2. GPR configuration. GPRconfig's non-Pro C++ discovery recognizes an
#    unprefixed g++, so the explicit cross g++ is presented through a
#    dedicated tools directory.
ln -s /usr/bin/aarch64-linux-gnu-g++-12 "$evidence/tools/g++"
config=$evidence/target.cgpr
"$tools/gprconfig" --batch --target="$target" \
    --config="Ada,,/usr/lib/gcc-cross/aarch64-linux-gnu/12" \
    --config="C++,,,$evidence/tools" -o "$config" \
    > "$logs/gprconfig.log" 2>&1 || fail "GPR configuration failed"
cp "$config" "$logs/target.cgpr"
{
    echo "geometry: $geometry_commit"
    echo "core: $core_commit"
    cat /etc/os-release
    dpkg-query -W gcc-12-aarch64-linux-gnu g++-12-aarch64-linux-gnu \
        gnat-12-aarch64-linux-gnu libgnat-12-arm64-cross \
        binutils-aarch64-linux-gnu qemu-user-static
    /usr/bin/aarch64-linux-gnu-gcc --version
    /usr/bin/aarch64-linux-gnu-g++-12 --version
    "$tools/gprbuild" --version
    sha256sum "$config"
} > "$logs/identities.log" 2>&1

export OPENCV_CROSS_TARGET="$target"
export ENV_PREFIX="$sysroot"
export OPENCV_CROSS_ADA=/usr/bin/aarch64-linux-gnu-gcc
export OPENCV_CROSS_CXX="$evidence/tools/g++"
export OPENCV_CROSS_RUNTIME=/usr/lib/gcc-cross/aarch64-linux-gnu/12
export OPENCV_CROSS_GPR_CONFIG="$config"
export OPENCV_CROSS_GPRBUILD="$tools/gprbuild"
export OPENCV_CROSS_GPRINSTALL="$tools/gprinstall"
export OPENCV_CROSS_PKG_CONFIG=/usr/bin/pkg-config
export OPENCV_CROSS_READELF=/usr/bin/readelf
export PKG_CONFIG_LIBDIR="$sysroot/usr/lib/aarch64-linux-gnu/pkgconfig"
export PKG_CONFIG_SYSROOT_DIR="$sysroot"
export OPENCV_CROSS_PROFILE=release
unset PKG_CONFIG_PATH GPR_PROJECT_PATH ADA_PROJECT_PATH CPATH
unset C_INCLUDE_PATH CPLUS_INCLUDE_PATH LIBRARY_PATH GCC_EXEC_PREFIX
unset COMPILER_PATH LD_LIBRARY_PATH ADA_INCLUDE_PATH ADA_OBJECTS_PATH

# 3. Core, by Core's own cross build at the exact commit. Its script runs
#    git without a safe.directory override; trust exactly that checkout in
#    this disposable environment.
git config --global --add safe.directory "$core_root"
sh "$core_root/scripts/cross_build_core.sh" --build "$evidence/core-work" \
    > "$logs/core-cross-build.log" 2>&1 || fail "Core cross build failed"
test "$(cat "$evidence/core-work/source-revision.txt")" = "$core_commit" \
    || fail "Core workspace is not from $core_commit"
core_prefix=$evidence/core-work/install
echo "CORE_AARCH64_CROSS_BUILD_INSTALL PASS ($core_commit)" >> "$dispositions"

# 4. Geometry, through the fail-closed cross configuration.
export OPENCV_CROSS_CORE_PREFIX="$core_prefix"
python3 "$root/scripts/cross_geometry.py" check \
    > "$logs/geometry-cross-check.json" 2> "$logs/geometry-cross-check.err" \
    || fail "Geometry cross check failed: $(cat "$logs/geometry-cross-check.err")"
sh "$root/scripts/cross_build_geometry.sh" --build "$evidence/geometry-work" \
    > "$logs/geometry-cross-build.log" 2>&1 \
    || fail "Geometry cross build failed; see $logs/geometry-cross-build.log"
work=$evidence/geometry-work
test "$(cat "$work/source-revision.txt")" = "$geometry_commit" \
    || fail "Geometry workspace is not from $geometry_commit"
for log in toolchain-probe.log production-build.log cross-evidence.json \
    opencv_geometry-install.log opencv_geometry_shim-install.log; do
    cp "$work/$log" "$logs/geometry-$log"
done
echo "GEOMETRY_AARCH64_CROSS_BUILD_INSTALL PASS ($geometry_commit)" \
    >> "$dispositions"

# 5. Independent consumers, against the installed prefixes, then against
#    both prefixes moved to new paths.
emulator=/usr/bin/qemu-aarch64-static
python3 "$here/qualify_reference_consumers.py" "$work/cross-evidence.json" \
    "$core_prefix" "$work/install" "$evidence/consumers-installed" \
    "$logs/consumers-installed" --emulator "$emulator" \
    > "$logs/consumers-installed.log" 2>&1 \
    || fail "installed consumers failed; see $logs/consumers-installed.log"
relocated=$evidence/relocated/a-longer-installation-root
mkdir -p "$relocated"
mv "$core_prefix" "$relocated/core-prefix-b"
mv "$work/install" "$relocated/geometry-prefix-b"
python3 "$here/qualify_reference_consumers.py" "$work/cross-evidence.json" \
    "$relocated/core-prefix-b" "$relocated/geometry-prefix-b" \
    "$evidence/consumers-relocated" "$logs/consumers-relocated" \
    --emulator "$emulator" > "$logs/consumers-relocated.log" 2>&1 \
    || fail "relocated consumers failed; see $logs/consumers-relocated.log"
echo "GEOMETRY_AARCH64_CONSUMER_LINK PASS (Ada and mixed; installed and" \
    "relocated)" >> "$dispositions"
echo "DEBIAN_AARCH64_EMULATED_CONSUMER_EXECUTION PASS (qemu-user; reference" \
    "only)" >> "$dispositions"

# 6. The complete AUnit suite, cross-built against the installed Core and
#    run under emulation.
cp -a "$aunit" "$evidence/aunit"
mkdir -p "$work/tests/config"
cp "$work/tests/gnat12/tests_config.gpr" "$work/tests/config/"
(
    cd "$work"
    GPR_PROJECT_PATH="$relocated/core-prefix-b/share/gpr:$evidence/aunit/lib/gnat:$work" \
        "$tools/gprbuild" --config="$config" -P tests/tests.gpr -p -j0 -v -R \
        -XGEOMETRY_GNAT12_PROFILE=release \
        -cargs:C++ "--sysroot=$sysroot" -largs "--sysroot=$sysroot" \
        > "$logs/aunit-cross-build.log" 2>&1
) || fail "AUnit cross build failed; see $logs/aunit-cross-build.log"
if grep -n 'warning:' "$logs/aunit-cross-build.log"; then
    fail "AUnit cross build has warnings"
fi
readelf -h "$work/tests/bin/tests" | grep -q 'Machine:.*AArch64' \
    || fail "the AUnit executable is not AArch64"
"$emulator" -L "$sysroot" "$work/tests/bin/tests" \
    > "$logs/aunit-emulated.log" 2>&1 \
    || fail "AUnit suite failed under emulation"
grep -qx "Total Tests Run:   $expected_tests" "$logs/aunit-emulated.log" \
    || fail "expected $expected_tests registered tests"
grep -qx "Successful Tests:  $expected_tests" "$logs/aunit-emulated.log" \
    || fail "not every AUnit test passed under emulation"
grep -qx 'Failed Assertions: 0' "$logs/aunit-emulated.log" || fail "failures"
grep -qx 'Unexpected Errors: 0' "$logs/aunit-emulated.log" || fail "errors"
{
    echo "DEBIAN_AARCH64_EMULATED_AUNIT PASS" \
        "($expected_tests/$expected_tests; qemu-user; reference only)"
    echo "TARGET_EXECUTION NOT RUN (no target hardware)"
    echo "ADACORE_YOCTO NOT ESTABLISHED (Debian reference toolchain and" \
        "sysroot)"
} >> "$dispositions"
cat "$dispositions"
